<?php
declare(strict_types=1);$active_module='channels';require_once __DIR__.'/layout.php';$u=$supplier_user;$pdo=db();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$code=strtolower(trim((string)($_POST['channel_code']??'')));$name=trim((string)($_POST['display_name']??''));if(!preg_match('/^[a-z0-9_]{2,60}$/',$code)||$name==='')$error='Kanal kodu ve adı zorunludur.';else $pdo->prepare("INSERT INTO channel_connections(supplier_id,channel_code,display_name,status) VALUES(?,?,?,'draft') ON CONFLICT(supplier_id,channel_code) DO UPDATE SET display_name=EXCLUDED.display_name")->execute([$u['supplier_id'],$code,$name]);}$q=$pdo->prepare('SELECT * FROM channel_connections WHERE supplier_id=? ORDER BY id DESC');$q->execute([$u['supplier_id']]);$rows=$q->fetchAll();supply_start('Kanal bağlantıları',$active_module);?><section class="page-intro"><p>OTA, acente ve doğrudan satış kanallarını bağlayın. Canlı bağlantılar kuyruk üzerinden fiyat, kontenjan ve rezervasyonları çift yönlü senkronize eder.</p></section><?php if($error):?><p class="login-error"><?=htmlspecialchars($error)?></p><?php endif;?><form method="post" class="supply-form"><div class="form-row"><label>Kanal kodu<input name="channel_code" placeholder="booking_com"></label><label>Görünen ad<input name="display_name" placeholder="Booking.com"></label></div><button>Bağlantı taslağı ekle</button></form><section class="next-module"><h2>Bağlantılar</h2><?php foreach($rows as $r):?><p><b><?=htmlspecialchars($r['display_name'])?></b> · <?=htmlspecialchars($r['channel_code'])?> · <?=htmlspecialchars($r['status'])?> <?= $r['last_error']?'· Hata: '.htmlspecialchars($r['last_error']):''?></p><?php endforeach;?></section><?php supply_end(); ?>
